// ── SÉCURITÉ : Anti-Prompt Injection + Limite taille ──────────────────────
function sanitizeInput(text) {
  if (!text || typeof text !== 'string') return text;

  // Limite taille : 50 000 chars max (environ 12 500 tokens)
  if (text.length > 50000) {
    text = text.substring(0, 50000) + '\n[TRONQUÉ — limite 50K chars atteinte]';
  }

  // Anti-prompt injection : neutraliser les tentatives d'override
  const injectionPatterns = [
    /ignore\s+(all\s+)?previous\s+instructions?/gi,
    /ignore\s+(toutes?\s+)?les?\s+instructions?\s+précédentes?/gi,
    /you\s+are\s+now\s+a/gi,
    /tu\s+es\s+maintenant/gi,
    /\[SYSTEM\]/gi,
    /\[INST\]/gi,
    /<\|system\|>/gi,
    /\[\[reset\]\]/gi,
  ];

  for (const pattern of injectionPatterns) {
    text = text.replace(pattern, '[FILTRÉ]');
  }

  return text;
}

var items = $input.all();

if (!items || items.length === 0) {
  return [{
    json: {
      valid: false,
      error: "Aucune donnée reçue du webhook",
      specs: null
    }
  }];
}

var inputJson = items[0].json;

// Extraire le body selon la structure reçue
var data = inputJson;

// Cas 1 : webhook retourne {headers, params, query, body, ...}
if (inputJson.body !== undefined) {
  var rawBody = inputJson.body;
  if (typeof rawBody === 'string') {
    // Supprimer le = parasite en préfixe si présent
    rawBody = rawBody.replace(/^=+/, '').trim();
    try {
      data = JSON.parse(rawBody);
    } catch(e) {
      data = inputJson;
    }
  } else if (typeof rawBody === 'object') {
    data = rawBody;
  }
}

// Cas 2 : les champs sont directement dans l'objet racine
var task_id     = data.task_id     || inputJson.task_id     || null;
var userRequest = sanitizeInput(data.userRequest || inputJson.userRequest || null);
var language    = data.language    || inputJson.language    || 'javascript';
var framework   = data.framework   || inputJson.framework   || 'express';
var architecture = data.architecture || inputJson.architecture || {};

if (!userRequest || userRequest.trim() === '') {
  return [{
