console.log("🟢 BACKEND V5.8 — SQLite + better-sqlite3");
var items = $input.all();
if (!items || items.length === 0) throw new Error("Aucune donnée reçue");
var inputData = items[0].json;

var arch         = inputData.architecture || {};
var endpoints    = inputData.priority_endpoints || arch.priority_endpoints || [];
var dataModel    = inputData.data_model   || arch.data_model   || {};
var stores       = inputData.stores       || arch.stores       || {};
var manifest     = arch.file_manifest     || [];
var improveMode  = inputData.improve_mode || false;
var sharedResources = inputData.shared_resources || arch.shared_resources || [];
var rbacRoles   = inputData.roles       || arch.roles       || [];
var rbacPerms   = inputData.permissions || arch.permissions || {};
var rbacEnabled = Array.isArray(rbacRoles) && rbacRoles.length > 0;
var _defRole    = (rbacRoles && rbacRoles[0]) || 'user';
var _allRoles   = rbacEnabled ? (rbacRoles.indexOf('admin') >= 0 ? rbacRoles.slice() : ['admin'].concat(rbacRoles)) : [];
function authChain(m, r) {
  if (!rbacEnabled) return 'authMiddleware';
  var key  = m.toUpperCase() + ' ' + r;
  var base = m.toUpperCase() + ' ' + r.replace(/\/:[^/]+$/, '');
  var allowed = rbacPerms[key] || rbacPerms[base];
  if (allowed && allowed.length) {
    var withAdmin = allowed.indexOf('admin') >= 0 ? allowed : ['admin'].concat(allowed);
    return 'authMiddleware, requireRole(' + withAdmin.map(function(x){ return "'" + String(x).replace(/'/g,'') + "'"; }).join(', ') + ')';
  }
  return 'authMiddleware';
}
var hasFrontend  = manifest.some(function(f){ return f.includes('frontend'); });
if (improveMode && !hasFrontend) { hasFrontend = true; }
// P4 : uploads securises actifs par defaut (fonctionnalite-vitrine securite).
var uploadsEnabled = inputData.uploads_enabled !== false;
var backendInstructions = inputData.backend_instructions || [];
var improvePrompt = inputData.userRequest || '';
var existingServerJs = inputData.existing_server_js || '';
var existingRoutes   = inputData.existing_routes    || [];
var existingStores   = inputData.existing_stores    || {};

// ── Construire la config ressources ───────────────────────────────────────
function getResourceConfig(path) {
  if (!path || path === '/health') return null;
  var seg = path.replace(/^\//, '').split('/')[0];
  for (var res in stores) {
    if (stores[res].store_name === seg) {
      return { resName: res, storeName: seg, requiredFields: stores[res].required_fields || [], fields: dataModel[res] || {}, shared: (stores[res].shared === true) || (sharedResources.indexOf(seg) >= 0) };
    }
  }
  var resName = seg.replace(/s$/, '');
  var fields  = dataModel[resName] || {};
  var required = Object.keys(fields).filter(function(k){ return !['id','created_at','updated_at','status'].includes(k); });
  return { resName: resName, storeName: seg, requiredFields: required, fields: fields };
}

// ── GARDE-FOU MODE AMÉLIORATION ───────────────────────────────────────────
if (improveMode && endpoints.length === 0 && existingRoutes.length > 0) {
  existingRoutes.forEach(function(r) {
    if (r.method && r.path) endpoints.push({ method: r.method, path: r.path, description: 'route conservée' });
  });
  if (Object.keys(existingStores).length > 0) {
    Object.keys(existingStores).forEach(function(rk) { if (!stores[rk]) stores[rk] = existingStores[rk]; });
  }
}

// ── Ajouter DELETE automatiquement ────────────────────────────────────────
var epPaths = endpoints.map(function(ep){ return ep.method + ep.path; });
endpoints.slice().forEach(function(ep) {
  if (ep.method === 'GET' && ep.path !== '/health' && !ep.path.includes(':')) {
    var delPath = ep.path + '/:id';
    if (!epPaths.includes('DELETE' + delPath)) {
      endpoints.push({ method: 'DELETE', path: delPath, description: 'supprimer par id' });
    }
    if (!epPaths.includes('PUT' + delPath)) {
      endpoints.push({ method: 'PUT', path: delPath, description: 'modifier par id' });
    }
  }
});

var storeNames = [];
endpoints.forEach(function(ep) {
  var cfg = getResourceConfig(ep.path);
  if (cfg && storeNames.indexOf(cfg.storeName) === -1) storeNames.push(cfg.storeName);
});

var resourceConfig = {};
storeNames.forEach(function(sn) {
  endpoints.forEach(function(ep) {
    var cfg = getResourceConfig(ep.path);
    if (cfg && cfg.storeName === sn && !resourceConfig[sn]) resourceConfig[sn] = cfg;
  });
});

// ── P5 : classification semantique deterministe d un champ -> type riche ───
// Source unique de verite (backend + frontend appliquent la meme). Honore un
// type explicite (objet { type, values }) si un normaliseur plus riche l emet ;
// sinon infere par le nom. On ne DEVINE jamais des valeurs d enum metier
// fragiles : la table d enums par defaut est limitee a des cas quasi-universels.
function classifyField(name, rawType) {
  var fl = String(name || '').toLowerCase();
  if (rawType && typeof rawType === 'object' && rawType.type) {
    var t = String(rawType.type).toLowerCase();
    if (t === 'enum')     return { kind: 'enum', values: (rawType.values || rawType.enum || []).map(String) };
    if (t === 'boolean' || t === 'bool') return { kind: 'boolean' };
    if (t === 'datetime') return { kind: 'datetime' };
    if (t === 'date')     return { kind: 'date' };
    if (t === 'number' || t === 'integer' || t === 'real' || t === 'float') return { kind: 'number' };
    if (t === 'longtext' || t === 'textarea') return { kind: 'longtext' };
    // 'text'/'string' -> on retombe sur l inference par nom ci-dessous
  }
  if (rawType === 'number') return { kind: 'number' };
  if (fl.endsWith('_id') && fl !== 'id') return { kind: 'fk' };
  var BOOL_WORDS = ['actif','active','inactif','disponible','indisponible','valide','invalide','publie','paye','regle','confirme','annule','archive','termine','complete','done','enabled','disabled','visible','cache','public','prive','urgent','favori','lu','vu','abonne','present','absent','ouvert','ferme','gratuit'];
  if (/^(is_|has_|est_)/.test(fl) || BOOL_WORDS.indexOf(fl) >= 0) return { kind: 'boolean' };
  var ENUMS = {
    priorite: ['basse','moyenne','haute','urgente'], priority: ['low','medium','high','urgent'],
    niveau: ['faible','moyen','eleve'], level: ['low','medium','high'],
    genre: ['Homme','Femme','Autre'], sexe: ['Homme','Femme','Autre'], civilite: ['M.','Mme','Autre'],
    frequence: ['quotidienne','hebdomadaire','mensuelle','annuelle']
  };
  if (ENUMS[fl]) return { kind: 'enum', values: ENUMS[fl] };
  if (/(datetime|date_?heure|horodat|timestamp)/.test(fl)) return { kind: 'datetime' };
  if (/(date|jour|naissance|deadline|echeance|debut|\bfin\b|expiration|peremption|validite)/.test(fl)) return { kind: 'date' };
  if (/(email|mail|courriel)/.test(fl)) return { kind: 'email' };
  if (/(telephone|\btel\b|phone|mobile|portable|whatsapp)/.test(fl)) return { kind: 'tel' };
  if (/(description|commentaire|message|motif|contenu|remarque|biographie|resume|note[s]?$|detail|adresse|observation)/.test(fl)) return { kind: 'longtext' };
  return { kind: 'text' };
}

// ── SQL TYPE MAPPING ──────────────────────────────────────────────────────
function sqlType(fieldName, fieldType) {
  if (['id'].includes(fieldName)) return 'INTEGER PRIMARY KEY AUTOINCREMENT';
  if (fieldName === 'created_at') return "TEXT DEFAULT (datetime('now'))";
  if (classifyField(fieldName, fieldType).kind === 'boolean') return 'INTEGER';
  if (fieldType !== 'number') return 'TEXT';
  var fLow = fieldName.toLowerCase();
  if (fLow.endsWith('_id')) return 'INTEGER';
  if (['latitude','longitude','prix','montant','poids','kilos','note','score'].some(function(k){ return fLow.includes(k); })) return 'REAL';
  return 'INTEGER';
}

function sqlTable(sn) {
  var cfg = resourceConfig[sn];
  if (!cfg) return '';
  var allFields = Object.assign({ id: 'number', created_at: 'string' }, cfg.fields);
  var lines = ['CREATE TABLE IF NOT EXISTS ' + sn + ' ('];
  var colDefs = [];
  colDefs.push('  id INTEGER PRIMARY KEY AUTOINCREMENT');
  Object.keys(cfg.fields).filter(function(k){ return k !== 'id' && k !== 'created_at'; }).forEach(function(k) {
    var sType = sqlType(k, cfg.fields[k]);
    // Booleen : INTEGER 0/1, toujours defini (defaut 0 si absent) -> pas de NOT NULL bloquant
    if (classifyField(k, cfg.fields[k]).kind === 'boolean') { colDefs.push('  ' + k + ' INTEGER NOT NULL DEFAULT 0'); return; }
    var notNull = cfg.requiredFields.includes(k) ? ' NOT NULL' : '';
    // FK reference
    var fkRef = '';
    if (k.endsWith('_id') && sType === 'INTEGER') {
      var refBase = k.replace(/_id$/, '');
      var refTable = refBase + 's';
      if (storeNames.includes(refTable)) fkRef = ' REFERENCES ' + refTable + '(id)';
      else if (storeNames.includes(refBase)) fkRef = ' REFERENCES ' + refBase + '(id)';
    }
    colDefs.push('  ' + k + ' ' + sType + notNull + fkRef);
  });
  colDefs.push('  ' + (cfg.shared ? 'created_by' : 'user_id') + ' INTEGER NOT NULL REFERENCES users(id)');
  colDefs.push("  created_at TEXT DEFAULT (datetime('now'))");
  lines.push(colDefs.join(',\n'));
  lines.push(');');
  return lines.join('\n');
}

// ── GÉNÉRER schema.sql ────────────────────────────────────────────────────
var schemaSql = '-- schema.sql — généré par Forge IA Backend V5.8\n-- Tables SQLite avec types TEXT / INTEGER / REAL\n\n';
schemaSql += 'CREATE TABLE IF NOT EXISTS users (\n' +
  '  id INTEGER PRIMARY KEY AUTOINCREMENT,\n' +
  '  username TEXT NOT NULL UNIQUE,\n' +
  '  password_hash TEXT NOT NULL,\n' +
  (rbacEnabled ? ("  role TEXT NOT NULL DEFAULT '" + _defRole + "',\n") : '') +
  "  created_at TEXT DEFAULT (datetime('now'))\n" +
  ');\n\n';
storeNames.forEach(function(sn) { schemaSql += sqlTable(sn) + '\n\n'; });
if (uploadsEnabled) {
  // P4 : table uploads — fichiers stockes en BLOB (aucun chemin disque => pas de path traversal au repos)
  schemaSql += 'CREATE TABLE IF NOT EXISTS uploads (\n' +
    '  id INTEGER PRIMARY KEY AUTOINCREMENT,\n' +
    '  user_id INTEGER NOT NULL REFERENCES users(id),\n' +
    '  filename TEXT NOT NULL,\n' +
    '  mimetype TEXT NOT NULL,\n' +
    '  size INTEGER NOT NULL,\n' +
    '  data BLOB NOT NULL,\n' +
    "  created_at TEXT DEFAULT (datetime('now'))\n" +
    ');\n\n';
}

// ── GÉNÉRER db.js ─────────────────────────────────────────────────────────
var dbJs = [
  "const Database = require('better-sqlite3');",
  "const path = require('path');",
  "const fs   = require('fs');",
  "",
  "const DB_PATH = process.env.DB_PATH || path.join(__dirname, 'database.db');",
  "const db = new Database(DB_PATH);",
  "",
  "// Activer WAL (performances) + cles etrangeres",
  "db.pragma('journal_mode = WAL');",
  "db.pragma('foreign_keys = ON');",
  "",
  "// Registre de migrations versionnees : chaque migration est appliquee une",
  "// seule fois. Base pour la generation additive idempotente du schema.",
  "db.exec(\"CREATE TABLE IF NOT EXISTS schema_migrations (id TEXT PRIMARY KEY, applied_at TEXT DEFAULT (datetime('now')))\");",
  "const _applied = new Set(db.prepare('SELECT id FROM schema_migrations').all().map(function(r){ return r.id; }));",
  "function applyMigration(id, sql) {",
  "  if (_applied.has(id)) return;",
  "  db.exec(sql);",
  "  db.prepare('INSERT INTO schema_migrations (id) VALUES (?)').run(id);",
  "  _applied.add(id);",
  "}",
