, function (req, res) {\n  try {\n    var filename = _safeName(req.body && req.body.filename);\n    var ext = (filename.indexOf('.') >= 0 ? filename.split('.').pop() : '').toLowerCase();\n    var spec = UPLOAD_TYPES[ext];\n    if (!spec) return res.status(400).json({ message: 'Extension non autorisee. Types acceptes : ' + Object.keys(UPLOAD_TYPES).join(', ') });\n    var b64 = String((req.body && req.body.data_base64) || '');\n    var comma = b64.indexOf(',');\n    if (b64.slice(0, 5) === 'data:' && comma > 0) b64 = b64.slice(comma + 1); // tolere les data: URLs\n    if (b64.length === 0 || !/^[A-Za-z0-9+/=\\r\\n]+$/.test(b64)) return res.status(400).json({ message: 'Donnees base64 invalides' });\n    if (b64.length > Math.ceil(UPLOAD_MAX_BYTES / 3) * 4 + 16) return res.status(413).json({ message: 'Fichier trop volumineux (max 5 Mo)' });\n    var buf = Buffer.from(b64, 'base64');\n    if (!buf.length) return res.status(400).json({ message: 'Fichier vide' });\n    if (buf.length > UPLOAD_MAX_BYTES) return res.status(413).json({ message: 'Fichier trop volumineux (max 5 Mo)' });\n    if (!_magicOk(buf, spec.magic)) return res.status(400).json({ message: 'Le contenu ne correspond pas a l extension (signature invalide)' });\n    var info = db.prepare('INSERT INTO uploads (user_id, filename, mimetype, size, data) VALUES (?, ?, ?, ?, ?)').run(req.user.sub, filename, spec.mime, buf.length, buf);\n    res.status(201).json({ id: info.lastInsertRowid, filename: filename, mimetype: spec.mime, size: buf.length });\n  } catch (e) { console.error('[POST /api/uploads]', e.message); res.status(500).json({ message: 'Erreur interne' }); }\n});\n\n// GET /api/uploads -- lister ses fichiers (metadonnees seules, jamais le BLOB)\napp.get('/api/uploads', authMiddleware, function (req, res) {\n  try { res.json(db.prepare('SELECT id, filename, mimetype, size, created_at FROM uploads WHERE user_id = ? ORDER BY id DESC').all(req.user.sub)); }\n  catch (e) { console.error('[GET /api/uploads]', 